from datetime import datetime, time


class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self._user_preferences: dict[str, dict[str, bool]] = {}

    def add_user(self, user: str) -> None:
        """Add a user with default notification preferences."""
        self._user_preferences[user] = {
            channel: (channel == "email") for channel in self.CHANNELS
        }

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        """Enable or disable a specific notification channel for a user."""
        if channel not in self.CHANNELS:
            raise ValueError(f"Invalid channel: {channel}. Must be one of {self.CHANNELS}")
        if user not in self._user_preferences:
            self.add_user(user)
        self._user_preferences[user][channel] = enabled

    def _is_quiet_hour(self, t: time) -> bool:
        """Check if a given time falls within the quiet hours interval."""
        if self.quiet_start <= self.quiet_end:
            return self.quiet_start <= t < self.quiet_end
        # Overnight range spanning midnight (e.g., 22:00 to 07:00)
        return t >= self.quiet_start or t < self.quiet_end

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self._user_preferences:
            self.add_user(user)

        preferences = self._user_preferences[user]
        quiet = self._is_quiet_hour(at.time())
        delivered = []

        for channel in self.CHANNELS:
            if not preferences.get(channel, False):
                continue

            # Email is always allowed; SMS and push are muted during quiet hours
            if quiet and channel in ("sms", "push"):
                continue

            delivered.append(channel)

        return delivered
